insert into public.catalog_sources select * from jsonb_to_recordset($catalog_data$[{"id":"leetcode","name":"LeetCode","url":"https://leetcode.com/problemset/","coverage":"DSA subset from the NeetCode community dataset; not the full LeetCode catalog","updated_on":"2026-11-02"},
{"id":"gfg","name":"GeeksforGeeks","url":"https://www.geeksforgeeks.org/dsa/dsa-sheet-by-love-babbar/","coverage":"Available GFG practice links from the published Love Babbar sheet; not all GFG questions","updated_on":"2026-11-02"},
{"id":"cses","name":"CSES","url":"https://cses.fi/problemset/","coverage":"All task links listed in the official problem-set snapshot","updated_on":"2026-11-02"},
{"id":"codeforces","name":"Codeforces","url":"https://codeforces.com/api/problemset.problems","coverage":"All contest problems returned by the official problemset API snapshot; excludes Gym/private sets","updated_on":"2026-11-02"}]$catalog_data$::jsonb) as x(id text,name text,url text,coverage text,updated_on date) on conflict (id) do update set name=excluded.name,url=excluded.url,coverage=excluded.coverage,updated_on=excluded.updated_on;

-- COMPACT CATALOG DATA
-- Repeated topic and tag names are encoded through dictionaries so the complete
-- single SQL file fits in the SQL Editor. Each numeric index is zero-based.
-- This retains the same 12,645 titles, links, ratings, tags and source metadata.
-- LeetCode/GFG/CSES rows below are:
-- [id,title,topic_index,difficulty_index,url,tag_indices,rating,access_index]
-- Difficulty dictionary: 0 Easy, 1 Medium, 2 Hard, 3 Unrated.
-- Access dictionary: 0 unknown, 1 free, 2 premium.
with dictionaries as (select $catalog_compact$["*special","1-D Dynamic Programming","2-D Dynamic Programming","2-sat","Additional Problems I","Additional Problems II","Advanced Graph Problems","Advanced Graphs","Advanced Techniques","Algorithms","Arrays","Arrays & hashing","Backtracking","Binary Search Tree:","Binary Trees","Binary search","Bit Manipulation:","Bit manipulation","Bitwise Operations","Construction Problems","Counting Problems","Disjoint sets","Dynamic programming","Geometry","Graph Algorithms","Graphs","Greedy","Heap","Heap / Priority Queue","Heaps & priority queues","Interactive Problems","Intervals","Introductory Problems","Linked List","Linked lists","LinkedList:","Math & Geometry","Mathematics","Matrix","Range queries","Recursion","Searching and Sorting:","Sliding Window Problems","Sliding window","Sorting","Sorting and Searching","Stack","Stacks","Stacks and Queues","String Algorithms","Strings","Tree Algorithms","Trees","Trie","Tries","Two pointers","bitmasks","brute force","chinese remainder theorem","combinatorics","communication","constructive algorithms","data structures","dfs and similar","divide and conquer","dp","dsu","expression parsing","fft","flows","games","geometry","graph matchings","hashing","implementation","interactive","math","matrices","meet-in-the-middle","number theory","probabilities","schedules","shortest paths","sortings","string suffix structures","ternary search"]$catalog_compact$::jsonb as tags, $catalog_compact$["Algorithms","Arrays & hashing","Backtracking","Binary search","Bit manipulation","Disjoint sets","Dynamic programming","Graphs","Greedy","Heaps & priority queues","Linked lists","Mathematics","Range queries","Recursion","Sliding window","Sorting","Stacks","Strings","Trees","Tries","Two pointers"]$catalog_compact$::jsonb as topics), rows as (select value as v from jsonb_array_elements($catalog_compact$[["lc:217","Contains Duplicate",1,0,"https://leetcode.com/problems/contains-duplicate/",[11],null,0],
["lc:242","Valid Anagram",1,0,"https://leetcode.com/problems/valid-anagram/",[11],null,0],
["lc:1929","Concatenation of Array",1,0,"https://leetcode.com/problems/concatenation-of-array/",[11],null,0],
["lc:1299","Replace Elements With Greatest Element On Right Side",1,0,"https://leetcode.com/problems/replace-elements-with-greatest-element-on-right-side/",[11],null,0],
["lc:392","Is Subsequence",1,0,"https://leetcode.com/problems/is-subsequence/",[11],null,0],
["lc:58","Length of Last Word",1,0,"https://leetcode.com/problems/length-of-last-word/",[11],null,0],
["lc:1","Two Sum",1,0,"https://leetcode.com/problems/two-sum/",[11],null,0],
["lc:14","Longest Common Prefix",1,0,"https://leetcode.com/problems/longest-common-prefix/",[11],null,0],
["lc:49","Group Anagrams",1,1,"https://leetcode.com/problems/group-anagrams/",[11],null,0],
