["lc:205","Isomorphic Strings",1,0,"https://leetcode.com/problems/isomorphic-strings/",[11],null,0],
["lc:605","Can Place Flowers",1,0,"https://leetcode.com/problems/can-place-flowers/",[11],null,0],
["lc:169","Majority Element",1,0,"https://leetcode.com/problems/majority-element/",[11],null,0],
["lc:496","Next Greater Element I",1,0,"https://leetcode.com/problems/next-greater-element-i/",[11],null,0],
["lc:724","Find Pivot Index",1,0,"https://leetcode.com/problems/find-pivot-index/",[11],null,0],
