insert into public.catalog_questions (id,source,source_id,platform,title,topic,url,tags,difficulty,access,source_rating,attribution,attribution_url,updated_on,sort_order)
select v->>0,
 case split_part(v->>0,':',1) when 'lc' then 'leetcode' when 'gfg' then 'gfg' else 'cses' end,
 split_part(v->>0,':',2),
 case split_part(v->>0,':',1) when 'lc' then 'LeetCode' when 'gfg' then 'GeeksforGeeks' else 'CSES' end,
 v->>1, d.topics->>((v->>2)::int), v->>4,
 array(select d.tags->>(t.value::int) from jsonb_array_elements_text(v->5) with ordinality as t(value,position) order by t.position),
 (array['Easy','Medium','Hard','Unrated'])[(v->>3)::int+1],
 (array['unknown','free','premium'])[(v->>7)::int+1], (v->>6)::int,
 case split_part(v->>0,':',1) when 'lc' then 'NeetCode community (MIT)' when 'gfg' then 'GFG / Love Babbar practice-link index' else 'CSES problem set' end,
 case split_part(v->>0,':',1) when 'lc' then 'https://github.com/neetcode-gh/leetcode' when 'gfg' then 'https://www.geeksforgeeks.org/dsa/dsa-sheet-by-love-babbar/' else 'https://cses.fi/problemset/' end,
 '2026-11-02'::date,
 case split_part(v->>0,':',1) when 'lc' then 10 when 'gfg' then 20 else 30 end
 from rows cross join dictionaries d
 on conflict (id) do update set source=excluded.source,source_id=excluded.source_id,platform=excluded.platform,title=excluded.title,topic=excluded.topic,url=excluded.url,tags=excluded.tags,difficulty=excluded.difficulty,access=excluded.access,source_rating=excluded.source_rating,attribution=excluded.attribution,attribution_url=excluded.attribution_url,updated_on=excluded.updated_on,sort_order=excluded.sort_order;

