insert into public.catalog_questions (id,source,source_id,platform,title,topic,url,tags,difficulty,access,source_rating,attribution,attribution_url,updated_on,sort_order)
select 'cf:'||(v->>0), 'codeforces', v->>0, 'Codeforces', v->>1,
 d.topics->>((v->>2)::int),
 coalesce(v->>5,'https://codeforces.com/problemset/problem/'||regexp_replace(v->>0,'^([0-9]+)(.+)$','\1/\2')),
 array(select d.tags->>(t.value::int) from jsonb_array_elements_text(v->3) with ordinality as t(value,position) order by t.position),
 'Unrated', 'free', (v->>4)::int, 'Codeforces official API',
 'https://codeforces.com/apiHelp', '2026-11-02'::date, 40
 from rows cross join dictionaries d
 on conflict (id) do update set source=excluded.source,source_id=excluded.source_id,platform=excluded.platform,title=excluded.title,topic=excluded.topic,url=excluded.url,tags=excluded.tags,difficulty=excluded.difficulty,access=excluded.access,source_rating=excluded.source_rating,attribution=excluded.attribution,attribution_url=excluded.attribution_url,updated_on=excluded.updated_on,sort_order=excluded.sort_order;

insert into public.catalog_collections (id,title,description,sort_order) select * from jsonb_to_recordset($catalog_data$[{"id":"neetcode150","title":"NeetCode 150","description":"Questions marked NeetCode 150 in the attributed community snapshot.","sort_order":0},
{"id":"blind75","title":"Blind 75","description":"Questions marked Blind 75 in the attributed community snapshot.","sort_order":1},
{"id":"gfg-practice","title":"GFG practice","description":"Available practice links across the GFG / Love Babbar topic sheet.","sort_order":2},
{"id":"cses","title":"CSES problem set","description":"The official CSES problem-set snapshot, across all sections.","sort_order":3},
{"id":"codeforces","title":"Codeforces problem set","description":"The public contest-problem snapshot from the official API.","sort_order":4}]$catalog_data$::jsonb) as x(id text,title text,description text,sort_order integer) on conflict (id) do update set title=excluded.title,description=excluded.description,sort_order=excluded.sort_order;

-- Source-wide collections are derived from the shared catalog without duplicating IDs.
insert into public.catalog_collection_items(collection_id,question_id)
 select case source when 'gfg' then 'gfg-practice' when 'cses' then 'cses' else 'codeforces' end,id
 from public.catalog_questions where source in ('gfg','cses','codeforces')
 on conflict do nothing;
-- Explicit membership for the attributed NeetCode 150 and Blind 75 selections.
